#include<bits/stdc++.h>

using namespace std;

using ll = long long;

void chmin(ll &a, ll b) {
    a = min(a, b);
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> a(n), b(m);
    for (int &i: a) cin >> i;
    for (int &i: b) cin >> i;
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    ll ans = 0;
    if (n & 1) {
        if (m & 1) ans += a.back();
        ans += accumulate(b.begin(), b.end(), 0LL);
        a.pop_back();
        --n;
    }
    if (m & 1) {
        ans += accumulate(a.begin(), a.end(), 0LL);
        b.pop_back();
        --m;
    }
    // pair の第 1 引数 : A_i または B_i
    //        第 2 引数 : 犬ならば 0、猫ならば 1
    vector<pair<int, int>> v;
    for (int i = 0; i < n; i++) v.emplace_back(a[i], 0);
    for (int i = 0; i < m; i++) v.emplace_back(b[i], 1);
    sort(v.begin(), v.end());

    vector dp(n + m + 1, vector(n + 1, vector<ll>(m + 1, 1LL << 60)));
    dp[0][0][0] = 0;
    int dog = 0, cat = 0;
    for (int i = 0; i < n + m; i++) {
        ll now = v[i].first;
        if (v[i].second == 0) {
            for (int j = 0; j <= dog; j++) {
                for (int k = 0; k <= cat; k++) {
                    chmin(dp[i + 1][j + 1][k], dp[i][j][k] + now * (m - k * 2));
                    chmin(dp[i + 1][j][k], dp[i][j][k] + now * (m - (cat - k) * 2));
                }
            }
            ++dog;
        } else {
            for (int j = 0; j <= dog; j++) {
                for (int k = 0; k <= cat; k++) {
                    chmin(dp[i + 1][j][k + 1], dp[i][j][k] + now * (n - j * 2));
                    chmin(dp[i + 1][j][k], dp[i][j][k] + now * (n - (dog - j) * 2));
                }
            }
            ++cat;
        }
    }
    ans += dp[n + m][n / 2][m / 2];
    cout << ans << endl;
}
